import placeholderUrl from '@/assets/nft-placeholder.svg'

// Variants generated by `npm run assets:optimize`: <name>-480.webp and <name>-960.webp.
const assets = import.meta.glob<string>('/src/assets/nfts/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
})

const byName = new Map(
  Object.entries(assets).map(([path, url]) => [path.split('/').pop()!.replace(/\.webp$/, ''), url]),
)

const WIDTH = { thumb: 480, full: 960 } as const

/** `file` is the artwork name stored by the fixtures ("ape-green.png"). */
export function resolveNftImage(file: string, size: keyof typeof WIDTH = 'full'): string {
  const stem = file.replace(/\.\w+$/, '')
  return byName.get(`${stem}-${WIDTH[size]}`) ?? placeholderUrl
}
